#!/bin/sh
# Format only the C port; pinned CUDA and generated ABI files stay untouched.
set -eu
cd "$(dirname "$0")/.."
fmt=${CLANG_FORMAT:-clang-format-18}
"$fmt" --version | grep -q 'version 18\.' || { echo 'clang-format 18 is required' >&2; exit 1; }
if [ "${1:-}" = --check ]; then
    set -- --dry-run --Werror
else
    set -- -i
fi
"$fmt" "$@" src/inkling_geometry.h src/inkling_quant.h src/cuda/geometry_contract.hpp src/cuda/capability.h src/cuda/target_profile.h src/cuda/launch_policy.hpp src/cuda/resource_policy.hpp src/cuda/prefill_resources.hpp test/cuda_policy.cpp test/numerical.c test/linear_shapes.cu test/conversion_oracles.cu test/cuda-stubs/cuda_runtime.h src/allocation_alignment.h src/file_map.h src/host_clock.h src/host_clock.c src/host_posix.c src/host_win.c test/platform.h test/filesystem.h test/host_clock.c test/platform_map.c test/abi_contract.c src/sha256.c src/sha256.h include/ifn_core.h test/native_benchmark.c test/host_cuda_errors.cpp test/hash.c examples/verify.c examples/generate.c examples/inspect.c test/mmap.c test/infer_consumer.c fuzz/fuzz_infer.c include/ifn_infer.h include/ifn_infer_inkling.h src/infer_internal.h src/infer.c src/infer_model.c src/infer_session.c src/infer_request.c src/engine_control.h test/infer.c test/infer_mock.c test/infer_native.c test/worker_lifetime.c test/worker_lifetime_mock.c include/ifn_chat.h src/chat.c src/stream.c include/ifn.h include/ifn_engine.h src/checked_prefill.h src/cuda/checked_prefill.cu src/engine_prefill.c src/lookup.h src/lookup.c src/engine_adaptive.c src/engine_prefix.c src/prefix.h src/sampling.c src/engine_spec.c src/engine_internal.h src/engine_bind.c src/engine_layout.c src/engine_forward.c src/engine_runtime.c include/ifn_gpu.h include/ifn_weights.h src/internal.h src/weights_internal.h src/weights_recipe.c src/weights_runtime.c src/gpu_cuda.c src/checked_cuda.h src/cuda/checked_weights.cu src/json.h src/json.c src/tokenizer.h src/tokenizer_profile.h src/tokenizer_load.c src/tokenizer.c src/inkling.h src/inkling.c src/foundation.c src/safetensors.c cli/generate.c cli/main.c test/sampling_kernels.cu test/session_context.cu test/lookup.c test/sampling.c test/mock_gpu.h test/engine.c test/adaptive_graph.cu test/adaptive_compare.c test/prefix_compare.c test/prefix_recovery.c test/decode_recovery.c test/decode_compare.c test/ar_compare.c test/chat_native.c fuzz/fuzz_stream.c test/chat.c test/stream_driver.c test/unit.c test/packing.cu test/gpu_context.cu test/gpu_weights_compare.c test/weights_runtime.c test/tokenizer.c test/inkling.c test/concurrency.c test/installed_gpu_consumer.c test/installed_consumer.c test/cuda_smoke.c fuzz/fuzz_safetensors.c fuzz/fuzz_tokenizer.c
